local M = class("FriendLikeLevelInfoModel", LikeOO.OODataBase)

function M:onCreate()
    M.super.onCreate(self)
    self:getData()
end

function M:onEnter()

end

function M:getAttrListData()
    if self.m_params.isCanLevelUp then
        return self.m_params.attrsData
    end
    local attrsData = clone(self.m_params.attrsData)
    -- 不够升一级就显示之前属性
    for index, itemData in ipairs(attrsData) do
        itemData.isNotChange = true
        local lastTempValue = itemData.curNum
        
        local key = GameUtil:getAttrsKey(itemData.attrKeyId)
        local curAttrValue = itemData.attrValue
        local lastAddAttrValue = -1
        if curAttrValue > 0 then
            local curNum = itemData.curAttrNumber
            if curNum > 0 then
                lastAddAttrValue = (curAttrValue / (1 + curNum)) * curNum
            else
                lastAddAttrValue = 0
            end
        end
        if lastAddAttrValue > 0 then
            lastAddAttrValue = math.floor(lastAddAttrValue)
            lastTempValue = lastTempValue .. "("..lastAddAttrValue..")"
        end
        itemData.lastNum = lastTempValue
    end
    return attrsData
end

return M

 
